<script setup>
import { ref, watch } from 'vue';
import { request } from '../api.js';
import { dateTime } from '../format.js';
import ErrorNotice from '../components/ErrorNotice.vue';
import AppDialog from '../components/AppDialog.vue';
const props = defineProps({ spaceId: { type: String, default: '' } });
const tab = ref('operations'), rows = ref([]), next = ref(null), error = ref(null), loading = ref(false), selected = ref(null), reason = ref(''), audit = ref(null), before = ref(null);
const usage = ref(null);
let loadRevision = 0;
const labels = { 'user.create': '创建账号', 'user.update': '修改账号', 'password.reset': '重置密码', 'password.change': '修改密码', 'membership.change': '修改成员权限', 'space.delete': '删除知识库', 'space.restore': '恢复知识库', 'session.login': '登录', 'conversation.audit_read': '查看问答审计', 'resource.post': '执行文档操作', 'resource.put': '更新资源', 'resource.patch': '修改资源', 'resource.delete': '删除资源' };
async function load(more = false) { const own = ++loadRevision; loading.value = true; error.value = null; try {
  const path = props.spaceId ? `/spaces/${props.spaceId}/audit-events` : tab.value === 'operations' ? '/admin/audit-events' : '/admin/conversation-audits';
  if (props.spaceId && !more) usage.value = await request(`/spaces/${props.spaceId}/usage`);
  const data = await request(`${path}?offset=${more ? next.value : 0}`); if (own !== loadRevision) return; rows.value = more ? [...rows.value, ...data.items] : data.items; next.value = data.next_offset;
} catch (cause) { if (own === loadRevision) error.value = cause; } finally { if (own === loadRevision) loading.value = false; } }
function open(row) { selected.value = row; reason.value = ''; audit.value = null; before.value = null; }
async function read(more = false) { loading.value = true; error.value = null; try { const data = await request(`/admin/conversation-audits/${selected.value.id}:read${more ? '?before=' + before.value : ''}`, { method: 'POST', body: JSON.stringify({ reason: reason.value.trim() }) }); audit.value = more ? { ...data, turns: [...data.turns, ...audit.value.turns] } : data; before.value = data.next_before; } catch (cause) { error.value = cause; } finally { loading.value = false; } }
watch([() => props.spaceId, tab], () => { selected.value = null; rows.value = []; load(); }, { immediate: true });
</script>
<template><div :class="spaceId ? 'panel account-panel' : 'page'"><div class="page-heading"><div><span v-if="!spaceId" class="eyebrow">ACTIVITY & AUDIT</span><h1>{{ spaceId ? '知识库操作记录' : '审计记录' }}</h1><p class="page-description">{{ spaceId ? '查看这个知识库的成员变更和管理操作。' : '追溯权限变更和管理操作。查看他人问答需要填写原因并留痕。' }}</p></div></div><nav v-if="!spaceId" class="tab-bar"><button class="btn ghost" :class="{ accent: tab === 'operations' }" @click="tab = 'operations'">操作记录</button><button class="btn ghost" :class="{ accent: tab === 'conversations' }" @click="tab = 'conversations'">问答审计</button></nav><ErrorNotice :error="error" retry @retry="load()"/><section v-if="usage" class="panel account-panel"><h3>本库用量</h3><div class="usage-facts"><span>图片模型调用 <strong>{{ usage.visual_processing.call_count }}</strong></span><span>缓存复用 <strong>{{ usage.visual_processing.cache_hits }}</strong></span><span>输入 / 输出 token <strong>{{ usage.visual_processing.input_tokens }} / {{ usage.visual_processing.output_tokens }}</strong></span><span>已知费用 <strong>¥ {{ Number(usage.visual_processing.known_cost_cny).toFixed(4) }}</strong></span><span>未定价调用 <strong>{{ usage.visual_processing.unpriced_calls }}</strong></span><span>问答会话数 <strong>{{ usage.conversation_count }}</strong></span></div><p v-if="usage.qa_token_usage" class="small">问答链路调用 {{ usage.qa_token_usage.call_count }} 次 · 输入 / 输出 token {{ usage.qa_token_usage.input_tokens }} / {{ usage.qa_token_usage.output_tokens }} · 已知费用 ¥ {{ Number(usage.qa_token_usage.known_cost_cny).toFixed(4) }} · 未定价 {{ usage.qa_token_usage.unpriced_calls }} 次</p><p v-else class="small muted">问答用量记录未启用。</p><p class="small muted">{{ usage.note }}</p></section><section class="panel table-scroll"><table class="data-table"><thead><tr><th>时间</th><th>{{ tab === 'operations' ? '操作' : '所属用户' }}</th><th>{{ tab === 'operations' ? '操作人 / 目标' : '所属知识库' }}</th><th/></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td class="nowrap">{{ dateTime(row.created_at) }}</td><td>{{ tab === 'operations' ? labels[row.action] || row.action : row.username || row.user_id }}</td><td class="small">{{ tab === 'operations' ? (row.actor_name || row.actor_id) : row.space_name || row.space_id }}<small v-if="tab === 'operations'" class="account-row-details">{{ row.target_name || row.target_id }}</small></td><td><button v-if="tab === 'conversations'" class="btn small" @click="open(row)">查看问答</button><details v-else><summary>详情</summary><p v-if="row.detail?.reason" class="small">{{ row.detail.reason }}</p><p v-if="row.detail?.before" class="small">{{ row.detail.before }} → {{ row.detail.after }}</p><p v-if="!Object.keys(row.detail || {}).length" class="small muted">操作已记录</p></details></td></tr></tbody></table><p v-if="!rows.length" class="muted account-panel">{{ loading ? '正在加载…' : '暂无记录' }}</p><footer v-if="next != null" class="table-footer"><button class="btn small" :disabled="loading" @click="load(true)">加载更多</button></footer></section><AppDialog :open="!!selected" title="问答审计" wide @close="selected = null; audit = null"><form v-if="!audit" @submit.prevent="read()"><p class="muted">这是独立的只读审计，不会进入或修改原用户会话。</p><label class="field-label" for="audit-reason">查看原因</label><textarea id="audit-reason" v-model="reason" required minlength="3" maxlength="500" placeholder="说明本次审计的目的"/><ErrorNotice :error="error"/><div class="dialog-actions"><button class="btn primary" :disabled="loading || reason.trim().length < 3">记录原因并查看</button></div></form><template v-else><h2>{{ audit.conversation.title }}</h2><p class="auth-message">历史审计快照，仅供追溯，不代表来源目前仍然有效。</p><button v-if="before" class="btn small" :disabled="loading" @click="read(true)">查看更早问答</button><article v-for="turn in audit.turns" :key="turn.sequence_number" class="audit-turn"><p class="audit-question">{{ turn.original_question }}</p><p>{{ turn.answer || '该轮没有可展示的已验证答案。' }}</p><small class="muted">{{ dateTime(turn.created_at) }}</small></article><p v-if="!audit.turns.length" class="muted">这个会话尚无问答。</p></template></AppDialog></div></temp